<script>setInterval(async()=>{if(document.hidden)return;const label=document.getElementById('nx-waf-refresh');try{const r=await fetch(<?= json_encode($wafUrl.'?api=realtime_logs', JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES) ?>);if(!r.ok)throw Error();const data=await r.json();if(data.status!=='success')throw Error();for(const [key,value] of Object.entries(data.metrics))document.querySelector('[data-waf-metric="'+key+'"]').textContent=new Intl.NumberFormat('es-UY').format(value);label.textContent='Actualizado '+new Date().toLocaleTimeString('es-UY')}catch{label.textContent='Actualización interrumpida'}},30000);</script>
